INSERT INTO "rules_rule" VALUES(704,'2023-11-15','2023-11-15 13:13:42.432313','Allonormativität ist eine Norm in unserer Gesellschaft, die davon ausgeht, dass jede Person Sex und eine romantische Beziehung haben will.','de','Allonormativität','n',0,1,NULL,NULL,NULL,'["Allonormativit\u00e4t"]','[{"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'Allonormativität','default','default',1,1,'allonormativität','n','["d_and_i"]',NULL,0);
INSERT INTO "rules_rule" VALUES(705,'2023-11-15','2023-11-15 13:13:43.135340','ἀνδρός andrós „Mann“, -philie von φιλία philía „Freundschaft“, „Liebe“), auch Androsexualität, bezeichnet die Neigung, sich emotional und sexuell zu Männern hingezogen zu fühlen','de','androsexuell','a',0,1,NULL,NULL,NULL,'["androsexuell"]','[{"word_type": "a", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'androsexuell','default','default',1,1,'androsexuell','a','["d_and_i"]',NULL,0);
