INSERT INTO "rules_rule" VALUES(708,'2023-11-15','2023-11-15 13:13:45.244581','Die Ballroom-Szene[1] (auch Ball Culture, drag ball culture, house-ballroom community und ähnliche Begriffe) beschreibt eine afroamerikanische und lateinamerikanische Bewegung in der US-amerikanischen LGBTQ-Szene, die in New York City ihren Ursprung nahm.','de','Ballroom','n',0,1,NULL,NULL,NULL,'["Ballroom"]','[{"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'Ballroom','default','default',1,1,'ballroom','n','["d_and_i"]',NULL,0);
