INSERT INTO "rules_rule" VALUES(710,'2023-11-15','2023-11-15 13:13:46.640782','Als bigender („beidgeschlechtlich“) definieren sich Personen, die sich mit beiden Geschlechtern männlich/weiblich identifizieren oder Elemente beider in sich vereinen, auch im Ausdruck.','de','Bigender','n',0,1,NULL,NULL,NULL,'["Bigender"]','[{"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'Bigender','default','default',1,1,'bigender','n','["d_and_i"]',NULL,0);
