INSERT INTO "rules_rule" VALUES(716,'2023-11-15','2023-11-15 13:13:51.119037','Kurz und knapp bedeutet cis*, dass man sich mit dem bei der Geburt zugeschriebenen Geschlecht identifiziert.','de','cis','a',0,1,NULL,NULL,NULL,'["cis"]','[{"word_type": "a", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'cis','default','default',1,1,'cis','a','["d_and_i"]',NULL,0);
