INSERT INTO "rules_rule" VALUES(731,'2023-11-15','2023-11-15 13:14:06.228778','“Gender Bender” leitet sich von Gender benden oder Gender bending ab. Bend kommt dabei aus dem Englischen und bedeutet so viel wie “biegen” oder “beugen”. Im Englischen gibt es einen Ausdruck “to bend (the) rules” – das meint, dass sich Menschen Regeln sehr großzügig auslegen, es nicht ganz so eng sehen, was erlaubt ist, oder wie die Regeln gemeint waren – also ein sehr laxes Umgang mit dem Erlaubten.','de','Gender Bending','|',0,1,NULL,NULL,NULL,'["Gender", "Bending"]','[{"word_type": "", "lower_case": true, "lemmatize": true}, {"word_type": "", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'Gender Bending','default','default',1,1,'gender','','["d_and_i"]',NULL,0);
