INSERT INTO "rules_rule" VALUES(741,'2023-11-15','2023-11-15 13:14:13.333252','Heterosexismus bezeichnet eine sexistische psychologische Einstellung und Ideologie, die Heterosexualität (gegengeschlechtliche Liebe) als überlegene oder einzig „natürliche“ Ausrichtung von menschlicher Sexualität vertritt und sexuelle Orientierungen von homosexuellen, bisexuellen, pansexuellen oder asexuellen Personen als „nicht normal“ abwertet und ablehnt','de','Heterosexismus','n',0,1,NULL,NULL,NULL,'["Heterosexismus"]','[{"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'Heterosexismus','default','default',1,1,'heterosexismus','n','["d_and_i"]',NULL,0);
