INSERT INTO "rules_rule" VALUES(745,'2023-11-15','2023-11-15 13:14:16.223261','Das politische Schlagwort Homonationalismus beschreibt eine Verbindung zwischen nationalistischen Ideologien und der LGBT-Bewegung und ihren Rechten. Der Begriff wurde erstmal von der Geschlechterforscherin Jasbir Puar im Jahre 2007 aufgebracht.','de','Homonationalismus','n',0,1,NULL,NULL,NULL,'["Homonationalismus"]','[{"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'Homonationalismus','default','default',1,1,'homonationalismus','n','["d_and_i"]',NULL,0);
