INSERT INTO "rules_rule" VALUES(767,'2023-11-15','2023-11-15 13:14:31.876467','Neutrois ist ein Geschlecht, das sich außerhalb des binären Geschlechtersystems befindet. Es fällt deshalb unter den Oberbegriff nicht-binär. Im Gegensatz zu Menschen, die agender sind (also kein Geschlecht haben), nehmen sich neutrois Menschen als klar einem Geschlecht zugehörig wahr: dem neutralen Geschlecht.','de','Neutrois','n',0,1,NULL,NULL,NULL,'["Neutrois"]','[{"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'Neutrois','default','default',1,1,'neutrois','n','["d_and_i"]',NULL,0);
INSERT INTO "rules_rule" VALUES(768,'2023-11-15','2023-11-15 13:14:33.295914','Outing ist eigentlich wenn die betreffende Person von Dritten geoutet wird. Coming-out macht die Person selbst','de','Outing','n',0,1,NULL,NULL,NULL,'["Outing"]','[{"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'Outing','default','default',1,1,'outing','n','["d_and_i"]',NULL,0);
