INSERT INTO "rules_rule" VALUES(793,'2023-11-15','2023-11-15 13:14:51.354149','Vogue oder Voguing bezeichnet einen Tanzstil, der in den 1970[1] Jahren in der Ballroom-Szene der marginalisierten homosexuellen Subkultur von New York Harlem entstand. Die Bezeichnung stammt entsprechend von der gleichnamigen Modezeitschrift Vogue. Der Tanz gilt als sehr expressiv und körperbetont und galt zu Entstehungszeiten als friedliche Art sich mit seinen Rivalen in der Szene zu duellieren und allgemein gesehen zu werden.','de','Voguing','n',0,1,NULL,NULL,NULL,'["Voguing"]','[{"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'Voguing','default','default',1,1,'voguing','n','["d_and_i"]',NULL,0);
