INSERT INTO "rules_rule" VALUES(803,'2023-11-15','2023-11-15 13:15:01.387106','Solche Ausdrücke lösen negative Assoziationen aus, und auch der „Spast“ hält schnell bei einem Wutausbruch hin und ist immer abwertend gemeint. Vielen behinderten Menschen ist daher eine neutrale Bezeichnung lieber, zum Beispiel der Fachausdruck. Der „Spastiker“ wird somit zum Mensch mit „Cerebralparese“.','de','Spast','n',0,1,NULL,NULL,1,'["Spast"]','[{"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'Spast','default','default',1,1,'spast','n','["ableism"]',NULL,0);
