INSERT INTO "rules_rule" VALUES(1937,'2023-11-15','2023-11-15 13:47:55.281932','„Invalide“ leitet sich aus dem Lateinischen ab und bedeutet soviel wie „kraftlos“, „schwach“ und „hinfällig“. Verwandt ist der Begriff mit Wörtern romanischer Sprachen, die zum Beispiel „unwert“, „ungültig“ oder „untauglich“ bezeichnen. Allein deswegen sollte man auf „invalide“ und „Invalidität“ verzichten – abgesehen davon sind diese Begriffe veraltet.','de','invalid','a',0,1,NULL,NULL,1,'["invalid"]','[{"word_type": "a", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'invalid','default','default',1,1,'invalid','a','["ability"]','nicht auf Menschen beziehen',0);
INSERT INTO "rules_rule" VALUES(1938,'2023-11-15','2023-11-15 13:47:57.349831','„Invalide“ leitet sich aus dem Lateinischen ab und bedeutet soviel wie „kraftlos“, „schwach“ und „hinfällig“. Verwandt ist der Begriff mit Wörtern romanischer Sprachen, die zum Beispiel „unwert“, „ungültig“ oder „untauglich“ bezeichnen. Allein deswegen sollte man auf „invalide“ und „Invalidität“ verzichten – abgesehen davon sind diese Begriffe veraltet.','de','Invalide','n',0,1,NULL,NULL,1,'["Invalide"]','[{"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'Invalide','default','default',1,1,'invalide','n','["ability"]',NULL,0);
INSERT INTO "rules_rule" VALUES(1939,'2023-11-15','2023-11-15 13:47:59.581675','„Invalide“ leitet sich aus dem Lateinischen ab und bedeutet soviel wie „kraftlos“, „schwach“ und „hinfällig“. Verwandt ist der Begriff mit Wörtern romanischer Sprachen, die zum Beispiel „unwert“, „ungültig“ oder „untauglich“ bezeichnen. Allein deswegen sollte man auf „invalide“ und „Invalidität“ verzichten – abgesehen davon sind diese Begriffe veraltet.','de','Invalidität','n',0,1,NULL,NULL,1,'["Invalidit\u00e4t"]','[{"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'Invalidität','default','default',1,1,'invalidität','n','["ability_advanced"]',NULL,0);
