INSERT INTO "rules_rule" VALUES(1961,'2023-11-15','2023-11-15 13:48:49.207989','Ein Rollstuhl ist keine Einschränkung, sondern ein Fortbewegungsmittel.Floskeln wie „an den Rollstuhl gefesselt“ oder „trotz der Behinderung” reduzieren behinderte Menschen auf ihre „Defizite“ und verstärken abwertende Bilder von Hilflosigkeit und Leid.','de','trotz ihrer Behinderung','~v|~|n',0,1,NULL,NULL,1,'["trotz", "ihrer", "Behinderung"]','[{"word_type": "v", "lower_case": true, "lemmatize": false}, {"word_type": "", "lower_case": true, "lemmatize": false}, {"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'trotz ihrer Behinderung','default','default',0,1,'trotz','v','["ability"]','nur erwähnen, wenn relevant',1);
