INSERT INTO "rules_rule" VALUES(2418,'2023-11-15','2023-11-15 14:15:24.943340','Gehörlose Menschen sind nicht „stumm“ oder „taubstumm“, sondern können genauso wie Hörende sprechen, entweder in der Gebärdensprache (die übrigens auch keine „Zeichensprache“ ist) oder lautsprachlich. „Gehörlos sein“ bzw. Gehörlosigkeit sind neutrale Begriffe, die deshalb von vielen nicht hörenden Menschen bevorzugt werden. Menschen, deren Hörvermögen eingeschränkt ist, bevorzugen Begriffe wie „schwerhörig“ oder „hörbeeinträchtigt“, manchmal auch „hörbehindert“.','de','taubstumm','a',0,1,NULL,NULL,1,'["taubstumm"]','[{"word_type": "a", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'taubstumm','default','default',1,1,'taubstumm','a','["hearing_advanced"]',NULL,0);
