INSERT INTO "rules_rule" VALUES(2545,'2023-11-15','2023-11-15 14:20:52.498080','Ein Rollstuhl ist keine Einschränkung, sondern ein Fortbewegungsmittel.Floskeln wie „an den Rollstuhl gefesselt“ oder „trotz der Behinderung” reduzieren behinderte Menschen auf ihre „Defizite“ und verstärken abwertende Bilder von Hilflosigkeit und Leid.Durch das Sprachbild werden Menschen nicht nur auf ihre Behinderung reduziert, auch eine Einschränkung der geistigen Mobilität schwingt bisweilen mit.','de','an den Rollstuhl gefesselt','|~|n|~',0,1,NULL,NULL,1,'["an", "den", "Rollstuhl", "gefesselt"]','[{"word_type": "", "lower_case": true, "lemmatize": true}, {"word_type": "", "lower_case": true, "lemmatize": false}, {"word_type": "n", "lower_case": true, "lemmatize": true}, {"word_type": "", "lower_case": true, "lemmatize": false}]',1,NULL,NULL,NULL,'an den Rollstuhl gefesselt','default','default',1,1,'an','','["mobility_advanced"]',NULL,1);
