INSERT INTO "rules_rule" VALUES(2984,'2023-11-15','2023-11-15 15:19:58.499374','Refers to people born with absent limbs, disfigurements, or other atypical appearances, or who later have amputations, burn scars, or other changes to their physical appearance that are stigmatized in society. Note that many people do not mind use of the words deformed or deformity, and others find the word disfigurement offensive.','en','deformed','~a',0,1,NULL,NULL,NULL,'["deformed"]','[{"word_type": "a", "lower_case": true, "lemmatize": false}]',1,NULL,NULL,NULL,'deformed','default','default',0,1,'deformed','a','["ability_advanced"]','Don''t use this word to describe a person',1);
