INSERT INTO "rules_rule" VALUES(3206,'2023-11-15','2023-11-15 15:27:38.656991','“Cougar/GILF” — Guess what? Older people have sex. There is no need to distinguish our sexuality from that of 23-year-old Instagram models. The sooner you embrace this, the better (and longer) your own sex life will be. Swipe right!','en','cougar','n',0,1,NULL,NULL,NULL,'["cougar"]','[{"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'cougar','default','default',1,1,'cougar','n','["age_old_advanced"]',NULL,0);
