INSERT INTO "rules_rule" VALUES(3220,'2023-11-15','2023-11-15 15:28:13.202401','“Grumpy old man” — Aging presents frustrating challenges, especially in our youth-oriented, pouty selfie-snapping culture. Maybe they’re not grumpy; maybe you are just being irritating. Get off their damn lawn already!','en','grumpy old man','a|a|n',0,1,NULL,NULL,NULL,'["grumpy", "old", "man"]','[{"word_type": "a", "lower_case": true, "lemmatize": true}, {"word_type": "a", "lower_case": true, "lemmatize": true}, {"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'grumpy old man','default','default',1,1,'grumpy','a','["age_old_advanced"]',NULL,0);
