INSERT INTO "rules_rule" VALUES(3224,'2023-11-15','2023-11-15 15:28:23.880015','“Old Coot” — What is a coot? Is it an insect? A toothy rodent? A weird skin growth? Do you even know what you’re calling us? Fun fact: A coot is a tough, adaptable water bird. They can fly and swim. Can you?','en','old coot','~a|~n',0,1,NULL,NULL,NULL,'["old", "coot"]','[{"word_type": "a", "lower_case": true, "lemmatize": false}, {"word_type": "n", "lower_case": true, "lemmatize": false}]',1,NULL,NULL,NULL,'old coot','default','default',0,1,'old','a','["age_old_advanced"]',NULL,1);
