INSERT INTO "rules_rule" VALUES(3229,'2023-11-15','2023-11-15 15:28:38.005955','“Over the hill” — Kid, no one knows what “the hill” is or what side of it any of us is on. Kindly reserve this term to estimate your location when we are a half mile ahead of you on a hike or in an intellectual conversation.','en','over-the-hill','a',0,1,NULL,NULL,NULL,'["over-the-hill"]','[{"word_type": "a", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'over-the-hill','default','default',1,1,'over-the-hill','a','["age_old_advanced"]',NULL,1);
