INSERT INTO "rules_rule" VALUES(3236,'2023-11-15','2023-11-15 15:28:52.070078','“She’s young at heart” or “I’ll always identify better with younger people.” Again, while probably intended to convey a positive connotation or framed as a compliment to another, these statements ring undertones of ‘young is good’, ‘older is bad.’ We challenge you to think through what it is you really mean. Are you referencing a high level of energy? Agility? Sense of humor or playfulness? GREAT- then say those words instead of generalizing perceived characteristics of any generation.','en','young at heart','a||~n',0,1,NULL,NULL,NULL,'["young", "at", "heart"]','[{"word_type": "a", "lower_case": true, "lemmatize": true}, {"word_type": "", "lower_case": true, "lemmatize": true}, {"word_type": "n", "lower_case": true, "lemmatize": false}]',1,NULL,NULL,NULL,'young at heart','default','default',1,1,'young','a','["age_old"]',NULL,1);
