INSERT INTO "rules_rule" VALUES(3240,'2023-11-15','2023-11-15 15:29:04.949508','“Entitled millennials…” While Second Acts’ aim is to raise up the talents, abilities and value of older adults, we must also be careful not to use stereotypes against other generations. Our organizations, workforces, and communities are strongest when all people are valued, included, and have the opportunity to contribute without stereotypes or bias.','en','millenial','n',0,1,NULL,NULL,NULL,'["millenial"]','[{"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'millenial','default','default',1,1,'millenial','n','["age_young_advanced"]',NULL,0);
