INSERT INTO "rules_rule" VALUES(3436,'2023-11-15','2023-11-15 15:41:06.735436','(UK, Southern & Southwest U.S.) someone who wants to be jewish, acts jewish or is jewish (also someone who is rich and owns a large amount of property)','en','jewbie','n',0,1,NULL,NULL,9,'["jewbie"]','[{"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'jewbie','default','default',1,1,'jewbie','n','["antisemitism"]',NULL,0);
