INSERT INTO "rules_rule" VALUES(3484,'2023-11-15','2023-11-15 15:42:44.362553','','en','That''s nuts','~n|~|a',0,1,NULL,NULL,NULL,'["That", "''s", "nuts"]','[{"word_type": "n", "lower_case": true, "lemmatize": false}, {"word_type": "", "lower_case": true, "lemmatize": false}, {"word_type": "a", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'That''s nuts','default','default',0,1,'that','n','["behavior"]',NULL,1);
INSERT INTO "rules_rule" VALUES(3485,'2023-11-15','2023-11-15 15:42:46.538660','Depicting Disabled people as having "unique" personalities, assuming a standard of non-disabled people as not having unique personalities can be disparaging and targeting them as atypical. Every human being has a unique personality and Disabled people are no different to non-disabled people in terms of personality formation.\ToClarify:
