INSERT INTO "rules_rule" VALUES(3500,'2023-11-15','2023-11-15 15:43:15.198443','The Christian Bible does not say to rest on Sundays. Saturday, the Sabbath, is the days of rest. Christian practice dedicating Sundays to worship celebrates the day Jesus rose from the dead. Historically, it was emperor Constantine who declared Sunday a rest day as "the Christian Sabbath" to differentiate between those following his state religion and those following older religious practices.','en','rest on Sunday','v||~n',0,1,NULL,NULL,NULL,'["rest", "on", "Sunday"]','[{"word_type": "v", "lower_case": true, "lemmatize": true}, {"word_type": "", "lower_case": true, "lemmatize": true}, {"word_type": "n", "lower_case": true, "lemmatize": false}]',1,NULL,NULL,NULL,'rest on Sunday','default','default',1,1,'rest','v','["belief_advanced"]','Only use in reference to religious practice',0);
INSERT INTO "rules_rule" VALUES(3501,'2023-11-15','2023-11-15 15:43:17.144646','The Christian Bible does not say to rest on Sundays. Saturday, the Sabbath, is the days of rest. Christian practice dedicating Sundays to worship celebrates the day Jesus rose from the dead. Historically, it was emperor Constantine who declared Sunday a rest day as "the Christian Sabbath" to differentiate between those following his state religion and those following older religious practices.','en','rest on Sundays','v||~n',0,1,NULL,NULL,NULL,'["rest", "on", "Sundays"]','[{"word_type": "v", "lower_case": true, "lemmatize": true}, {"word_type": "", "lower_case": true, "lemmatize": true}, {"word_type": "n", "lower_case": true, "lemmatize": false}]',1,NULL,NULL,NULL,'rest on Sundays','default','default',1,1,'rest','v','["belief_advanced"]','Only use in reference to religious practice',0);
INSERT INTO "rules_rule" VALUES(3502,'2023-11-15','2023-11-15 15:43:19.139177','The Christian Bible does not say to rest on Sundays. Saturday, the Sabbath, is the days of rest. Christian practice dedicating Sundays to worship celebrates the day Jesus rose from the dead. Historically, it was emperor Constantine who declared Sunday a rest day as "the Christian Sabbath" to differentiate between those following his state religion and those following older religious practices.','en','Sunday is a day of rest','~n|~v||n||~n',0,1,NULL,NULL,NULL,'["Sunday", "is", "a", "day", "of", "rest"]','[{"word_type": "n", "lower_case": true, "lemmatize": false}, {"word_type": "v", "lower_case": true, "lemmatize": false}, {"word_type": "", "lower_case": true, "lemmatize": true}, {"word_type": "n", "lower_case": true, "lemmatize": true}, {"word_type": "", "lower_case": true, "lemmatize": true}, {"word_type": "n", "lower_case": true, "lemmatize": false}]',1,NULL,NULL,NULL,'Sunday is a day of rest','default','default',0,1,'sunday','n','["belief_advanced"]','Only use in reference to religious practice',0);
