INSERT INTO "rules_rule" VALUES(4400,'2023-11-15','2023-11-15 16:10:41.167208','Refers to people born with absent limbs, disfigurements, or other atypical appearances, or who later have amputations, burn scars, or other changes to their physical appearance that are stigmatized in society. Note that many people do not mind use of the words deformed or deformity, and others find the word disfigurement offensive.','en','bound to a wheelchair','~a|||n',0,1,NULL,NULL,NULL,'["bound", "to", "a", "wheelchair"]','[{"word_type": "a", "lower_case": true, "lemmatize": false}, {"word_type": "", "lower_case": true, "lemmatize": true}, {"word_type": "", "lower_case": true, "lemmatize": true}, {"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'bound to a wheelchair','default','default',0,1,'bound','a','["mobility"]',NULL,1);
