INSERT INTO "rules_rule" VALUES(4406,'2023-11-15','2023-11-15 16:10:59.782184','Refers to people with mental or psychiatric disabilities. Often used as a metaphor.','en','gimp','n',0,1,NULL,NULL,NULL,'["gimp"]','[{"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'gimp','default','default',1,1,'gimp','n','["mobility_advanced"]',NULL,0);
INSERT INTO "rules_rule" VALUES(4407,'2023-11-15','2023-11-15 16:11:02.861729','Refers to fat people/people of size. Note that per many fat activists , it''s often completely acceptable to use the word "fat" as a description, so long as it''s not used as a pejorative in and of itself.','en','incapacitated','~a',0,1,NULL,NULL,NULL,'["incapacitated"]','[{"word_type": "a", "lower_case": true, "lemmatize": false}]',1,NULL,NULL,NULL,'incapacitated','default','default',0,1,'incapacitated','a','["mobility_advanced"]',NULL,1);
