INSERT INTO "rules_rule" VALUES(4675,'2023-11-15','2023-11-15 16:15:14.525375','A way to exempt some people from a change because of conditions that existed before the change (e.g. we’ve grandfathered some users on an unlimited data plan.”) The term “grandfather clause” originated in the American South in the 1890s as a way to defy the 15th Amendment and prevent black Americans from voting. A good alternative might be “legacy”','en','grandfather clause','~n|n',0,1,NULL,NULL,10,'["grandfather", "clause"]','[{"word_type": "n", "lower_case": true, "lemmatize": false}, {"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'grandfather clause','default','default',0,1,'grandfather','n','["racist_source_advanced"]',NULL,0);
