INSERT INTO "rules_rule" VALUES(4678,'2023-11-15','2023-11-15 16:15:20.847379','"Gyp" or "gip" most likely evolved as a shortened version of "gypsy" — more correctly known as the Romani, an ethnic group now mostly in Europe and America. The Romani typically traveled a lot and made their money by selling goods. Business disputes naturally arose, and the masses started thinking of Romani as swindlers.','en','gyp','n',0,1,NULL,NULL,NULL,'["gyp"]','[{"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'gyp','default','default',1,1,'gyp','n','["racist_source_advanced"]',NULL,0);
