INSERT INTO "rules_rule" VALUES(4690,'2023-11-15','2023-11-15 16:16:00.159518','The origin of this phrase is disputed. Some claim the expression originated in feudal Japanese times in reference to the practice of proving no weapons were hidden within the folds of clothing. Others claim this bit of business jargon emerged from fears in the U.S. about the rise of Japan’s economy in the ’80s.','en','open the kimono','v||~n',0,1,NULL,NULL,NULL,'["open", "the", "kimono"]','[{"word_type": "v", "lower_case": true, "lemmatize": true}, {"word_type": "", "lower_case": true, "lemmatize": true}, {"word_type": "n", "lower_case": true, "lemmatize": false}]',1,NULL,NULL,NULL,'open the kimono','default','default',1,1,'open','v','["racist_source_advanced"]',NULL,0);
