INSERT INTO "rules_rule" VALUES(4943,'2023-11-15','2023-11-15 16:25:09.128855','United States	Hispanic people	First recorded use in 1915. Believed to be a play on a Spanish-accented pronunciation of the English word speak. May apply to Spanish speakers in general.','en','spic','n',0,1,NULL,NULL,9,'["spic"]','[{"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'spic','default','default',1,1,'spic','n','["xenophobia"]',NULL,0);
INSERT INTO "rules_rule" VALUES(4944,'2023-11-15','2023-11-15 16:25:10.070428','United States	Hispanic people	First recorded use in 1915. Believed to be a play on a Spanish-accented pronunciation of the English word speak. May apply to Spanish speakers in general.','en','spick','n',0,1,NULL,NULL,9,'["spick"]','[{"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'spick','default','default',1,1,'spick','n','["xenophobia"]',NULL,0);
INSERT INTO "rules_rule" VALUES(4945,'2023-11-15','2023-11-15 16:25:11.066654','United States	Hispanic people	First recorded use in 1915. Believed to be a play on a Spanish-accented pronunciation of the English word speak. May apply to Spanish speakers in general.','en','spig','n',0,1,NULL,NULL,9,'["spig"]','[{"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'spig','default','default',1,1,'spig','n','["xenophobia"]',NULL,0);
INSERT INTO "rules_rule" VALUES(4946,'2023-11-15','2023-11-15 16:25:12.083894','United States	Hispanic people	First recorded use in 1915. Believed to be a play on a Spanish-accented pronunciation of the English word speak. May apply to Spanish speakers in general.','en','spik','n',0,1,NULL,NULL,9,'["spik"]','[{"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'spik','default','default',1,1,'spik','n','["xenophobia"]',NULL,0);
INSERT INTO "rules_rule" VALUES(4947,'2023-11-15','2023-11-15 16:25:13.037706','This phrase is uttered by Willem Dafoe''s character (Charlie) in the film Born on the Fourth of July.','en','taco-head','n',0,1,NULL,NULL,9,'["taco-head"]','[{"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'taco-head','default','default',1,1,'taco-head','n','["xenophobia"]',NULL,0);
INSERT INTO "rules_rule" VALUES(4948,'2023-11-15','2023-11-15 16:25:14.071821','United States	Undocumented immigrants	Refers to illegal immigrant residing in the United States. Originally applied specifically to Mexican migrant workers who had illegally crossed the United States border via the Rio Grande river to find work in the United States, its meaning has since broadened to anyone who illegally enters the United States through its southern border.','en','wetback','n',0,1,NULL,NULL,9,'["wetback"]','[{"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'wetback','default','default',1,1,'wetback','n','["xenophobia"]',NULL,0);
INSERT INTO "rules_rule" VALUES(4949,'2023-11-15','2023-11-15 16:25:15.226207','British English speakers	Americans	A contraction of "Yankee" below, first recorded in 1778 and employed internationally by speakers of British English in informal reference to all Americans generally.','en','yank','n',0,1,NULL,NULL,9,'["yank"]','[{"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'yank','default','default',1,1,'yank','n','["xenophobia"]',NULL,0);
INSERT INTO "rules_rule" VALUES(4950,'2023-11-15','2023-11-15 16:25:16.276056','Dutch speakers	Americans	Possibly from Janke ("Johnny") or a dialectical variant of Jan Kaas ("John Cheese"). First applied by the Dutch colonists of New Amsterdam to Connecticuters and then to other residents of New England, "Yankee" remains in use in the American South in reference to Northerners, often in a mildly pejorative sense. Outside the US, especially in Spain and South America, used to describe all citizens of the US, regardless of which part of the US they come from.','en','yankee','n',0,1,NULL,NULL,9,'["yankee"]','[{"word_type": "n", "lower_case": true, "lemmatize": true}]',1,NULL,NULL,NULL,'yankee','default','default',1,1,'yankee','n','["xenophobia"]',NULL,0);
